<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue';
type Request=(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<any>;
const props=defineProps<{section:string;request:Request;readonly:boolean;access:any}>();
const busy=ref(false),error=ref(''),notice=ref(''),items=ref<any[]>([]),total=ref(0),selected=ref<any|null>(null),owners=ref<any[]>([]),customers=ref<any[]>([]),categories=ref<any[]>([]),ticketTypes=ref<any[]>([]);
const title=computed(()=>({tickets:'工单与 SLA',knowledge:'知识库',campaigns:'营销活动',integrations:'开放集成'} as any)[props.section]??'P3 业务中心');
const canWrite=computed(()=>!props.readonly&&(props.section==='tickets'?props.access?.tickets?.write:props.section==='knowledge'?props.access?.knowledgeWrite:props.section==='campaigns'?props.access?.campaigns?.write:props.access?.integrationManage));
const createOpen=ref(false),requestKey=ref('');
const form=reactive({title:'',description:'',customerId:'',assigneeMemberId:'',priority:'NORMAL',typeCode:'GENERAL',requesterName:'',requesterEmail:'',categoryId:'',body:'',name:'',channel:'FOLLOW_UP',budgetYuan:0,subject:'',taskDueDate:new Date(Date.now()+86400000).toISOString().slice(0,10)});
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
async function load(){selected.value=null;const path=props.section==='tickets'?'/tickets?pageSize=50':props.section==='knowledge'?'/knowledge/articles?pageSize=50':props.section==='campaigns'?'/campaigns?pageSize=50':'/integrations/keys';const data=await props.request(path);items.value=Array.isArray(data)?data:(data.items??[]);total.value=data.total??items.value.length;}
async function prepare(){requestKey.value=crypto.randomUUID();createOpen.value=true;if(props.section==='tickets'){const [o,c,config]=await Promise.all([props.request('/tickets/owners'),props.request('/tickets/customer-options?pageSize=100'),props.request('/configuration').catch(()=>({dictionaries:[]}))]);owners.value=o;customers.value=c.items??[];ticketTypes.value=(config.dictionaries??[]).filter((x:any)=>x.dictionaryType==='TICKET_TYPE'&&x.active);form.assigneeMemberId=owners.value[0]?.id??'';form.customerId=customers.value[0]?.id??'';form.typeCode=ticketTypes.value[0]?.itemCode??'GENERAL';}if(props.section==='knowledge'){categories.value=await props.request('/knowledge/categories');form.categoryId=categories.value.find((x:any)=>x.active)?.id??'';}if(props.section==='campaigns'){owners.value=await props.request('/campaigns/owners');form.assigneeMemberId=owners.value[0]?.id??'';}}
async function create(){await run(async()=>{if(props.section==='tickets')await props.request('/tickets','POST',{title:form.title,description:form.description,customerId:form.customerId||null,assigneeMemberId:form.assigneeMemberId,priority:form.priority,slaPolicyId:null,requesterName:form.requesterName,requesterEmail:form.requesterEmail,expectedVersion:0,typeCode:form.typeCode},{'Idempotency-Key':requestKey.value});else if(props.section==='knowledge')await props.request('/knowledge/articles','POST',{categoryId:form.categoryId,title:form.title,body:form.body,expectedVersion:0},{'Idempotency-Key':requestKey.value});else if(props.section==='campaigns')await props.request('/campaigns','POST',{name:form.name,description:form.description,ownerMemberId:form.assigneeMemberId,channel:form.channel,budgetCents:Math.round(Number(form.budgetYuan)*100),subject:form.subject,body:form.body,taskDueDate:form.taskDueDate,expectedVersion:0},{'Idempotency-Key':requestKey.value});createOpen.value=false;notice.value='已保存';await load();});}
async function open(row:any){await run(async()=>{selected.value=await props.request(props.section==='tickets'?'/tickets/'+row.id:props.section==='knowledge'?'/knowledge/articles/'+row.id:props.section==='campaigns'?'/campaigns/'+row.id:'/integrations/keys');});}
async function ticketAction(action:string){if(!selected.value)return;await run(async()=>{const reason=prompt(action==='resolve'?'填写解决说明':'填写处理说明')?.trim();if(!reason)return;selected.value=await props.request(`/tickets/${selected.value.id}/${action}`,'POST',{expectedVersion:selected.value.version,reason},{'Idempotency-Key':crypto.randomUUID()});notice.value='工单状态已更新';await load();});}
async function reply(){if(!selected.value)return;const body=prompt('填写公开回复')?.trim();if(!body)return;await run(async()=>{selected.value=await props.request(`/tickets/${selected.value.id}/comments`,'POST',{expectedVersion:selected.value.version,body,kind:'PUBLIC_REPLY'},{'Idempotency-Key':crypto.randomUUID()});notice.value='公开回复已记录';});}
async function knowledgeAction(action:string){if(!selected.value)return;await run(async()=>{selected.value=await props.request(`/knowledge/articles/${selected.value.id}/${action}`,'POST',{expectedVersion:selected.value.version,reason:action==='archive'?'归档知识':''},{'Idempotency-Key':crypto.randomUUID()});notice.value='知识状态已更新';await load();});}
watch(()=>props.section,()=>run(load));onMounted(()=>run(load));
</script>

<template>
 <section class="p3">
  <div class="page-heading"><div><span class="eyebrow">P3 BUSINESS OPERATIONS</span><h1>{{title}}</h1><p>{{section==='tickets'?'处理客户服务、公开回复与 SLA 节点。':section==='knowledge'?'沉淀可发布、可追溯版本的服务知识。':section==='campaigns'?'按许可管理活动、目标和执行结果。':'管理签名 API、Webhook 与投递队列。'}}</p></div><button v-if="canWrite&&section!=='integrations'" class="btn primary" @click="prepare">新增</button></div>
  <div v-if="error" class="p3-alert bad">{{error}}</div><div v-if="notice" class="p3-alert ok">{{notice}}</div>
  <section class="card p3-card"><div class="p3-bar"><strong>{{total}} 条记录</strong><button class="btn secondary" :disabled="busy" @click="run(load)">刷新</button></div><div class="table-scroll"><table><thead><tr><th>名称 / 编号</th><th>状态</th><th>负责人 / 类型</th><th>更新时间</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td><strong>{{row.ticketNumber||row.title||row.name}}</strong><small>{{row.title&&row.ticketNumber?row.title:row.description||row.email||''}}</small></td><td><span class="badge neutral">{{row.status||'有效'}}</span></td><td>{{row.assigneeName||row.authorName||row.ownerName||row.typeCode||'—'}}</td><td>{{row.updatedAt?new Date(row.updatedAt).toLocaleString():'—'}}</td><td><button class="text-button" @click="open(row)">查看</button></td></tr><tr v-if="!items.length"><td colspan="5" class="empty-cell">{{busy?'正在加载…':'暂无记录'}}</td></tr></tbody></table></div></section>
  <section v-if="selected" class="card p3-detail"><div class="p3-bar"><div><span class="eyebrow">RECORD DETAIL</span><h2>{{selected.ticketNumber||selected.title||selected.name}}</h2></div><button class="text-button" @click="selected=null">关闭</button></div><p v-if="selected.description||selected.body" class="p3-copy">{{selected.description||selected.body}}</p><dl><template v-for="(value,key) in selected" :key="String(key)"><template v-if="!['description','body','slaSnapshot','payload','scopes','events','canWrite','canManage'].includes(String(key))&&typeof value!=='object'"><dt>{{key}}</dt><dd>{{value??'—'}}</dd></template></template></dl><div v-if="section==='tickets'&&!readonly&&selected.canWrite" class="p3-actions"><button class="btn secondary" @click="reply">公开回复</button><button v-if="selected.status==='NEW'" class="btn secondary" @click="ticketAction('start')">开始处理</button><button v-if="selected.status==='IN_PROGRESS'" class="btn secondary" @click="ticketAction('resolve')">解决</button><button v-if="selected.status==='RESOLVED'" class="btn secondary" @click="ticketAction('close')">关闭</button></div><div v-if="section==='knowledge'&&!readonly&&selected.canManage" class="p3-actions"><button v-if="selected.canPublish" class="btn primary" @click="knowledgeAction('publish')">发布</button><button v-if="selected.status==='PUBLISHED'" class="btn secondary" @click="knowledgeAction('revise')">转回草稿</button><button v-if="selected.status!=='ARCHIVED'" class="btn secondary" @click="knowledgeAction('archive')">归档</button></div></section>
  <div v-if="createOpen" class="modal-backdrop" @click.self="createOpen=false"><form class="p3-modal" @submit.prevent="create"><div class="p3-bar"><h2>新增{{title}}</h2><button type="button" class="text-button" @click="createOpen=false">关闭</button></div><template v-if="section==='tickets'"><label>主题<input v-model="form.title" required maxlength="200"/></label><label>客户<select v-model="form.customerId"><option value="">不关联客户</option><option v-for="c in customers" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label>负责人<select v-model="form.assigneeMemberId" required><option v-for="o in owners" :value="o.id" :key="o.id">{{o.name}}</option></select></label><div class="p3-grid"><label>优先级<select v-model="form.priority"><option value="URGENT">紧急</option><option value="HIGH">高</option><option value="NORMAL">普通</option><option value="LOW">低</option></select></label><label>工单类型<select v-model="form.typeCode"><option v-for="t in ticketTypes" :value="t.itemCode" :key="t.id">{{t.label}}</option></select></label></div><label>说明<textarea v-model="form.description" rows="5" maxlength="10000"></textarea></label></template><template v-else-if="section==='knowledge'"><label>标题<input v-model="form.title" required maxlength="200"/></label><label>分类<select v-model="form.categoryId" required><option v-for="c in categories.filter(x=>x.active)" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label>正文<textarea v-model="form.body" required rows="10" maxlength="20000"></textarea></label></template><template v-else><label>活动名称<input v-model="form.name" required maxlength="200"/></label><label>负责人<select v-model="form.assigneeMemberId" required><option v-for="o in owners" :value="o.id" :key="o.id">{{o.name}}</option></select></label><label>渠道<select v-model="form.channel"><option value="FOLLOW_UP">跟进任务</option><option value="EMAIL_DRAFT">邮件草稿</option></select></label><label>主题<input v-model="form.subject" required maxlength="200"/></label><label>内容<textarea v-model="form.body" required rows="6" maxlength="4000"></textarea></label><label>任务日期<input v-model="form.taskDueDate" type="date" required/></label></template><div v-if="error" class="p3-alert bad">{{error}}</div><button class="btn primary" :disabled="busy">{{busy?'正在保存…':'保存'}}</button></form></div>
 </section>
</template>

<style scoped>
.p3-card{overflow:hidden}.p3-bar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px}.p3-bar h2{margin:0}.p3 table small{display:block;margin-top:5px;color:#728078}.p3-detail{padding:6px 22px 24px;margin-top:20px}.p3-copy{white-space:pre-wrap;line-height:1.8;color:#4d6255;padding:0 20px}.p3-detail dl{display:grid;grid-template-columns:160px 1fr;gap:0;margin:10px 20px}.p3-detail dt,.p3-detail dd{padding:9px;border-bottom:1px solid #e8ede9;font-size:13px}.p3-detail dt{color:#6b786f}.p3-actions{display:flex;gap:10px;flex-wrap:wrap;padding:18px 20px}.p3-alert{padding:12px 15px;border-radius:7px;margin:12px 0;font-size:13px}.p3-alert.bad{background:#fff0f1;color:#9d2433}.p3-alert.ok{background:#eaf5ed;color:#286045}.p3-modal{width:min(620px,calc(100vw - 30px));max-height:calc(100dvh - 40px);overflow:auto;background:#fff;border-radius:12px;padding:10px 24px 28px}.p3-modal label{display:flex;flex-direction:column;gap:8px;margin:15px 0;font-size:13px;color:#3c5344}.p3-modal input,.p3-modal select,.p3-modal textarea{padding:11px;border:1px solid #cbd7cf;border-radius:6px;background:#fff}.p3-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:650px){.p3-detail dl{grid-template-columns:1fr}.p3-detail dt{border-bottom:0;padding-bottom:0}.p3-grid{grid-template-columns:1fr}}
</style>
